// runs the WebSocket matchmaking on the same port.
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { join, extname, normalize } from 'node:path';
import { networkInterfaces } from 'node:os';
import { WebSocketServer, WebSocket } from 'ws';

const PORT = process.env.PORT || 3000;
const DIST = join(process.cwd(), 'dist');
const MIME = {
  '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css',
  '.png': 'image/png', '.ico': 'image/x-icon', '.svg': 'image/svg+xml',
};

const httpServer = createServer(async (req, res) => {
  let path = normalize(decodeURIComponent(req.url.split('?')[0])).replace(/^([/\\])+/, '');
  if (path === '' || path === '.') path = 'index.html';
  try {
    const data = await readFile(join(DIST, path));
    res.writeHead(200, { 'Content-Type': MIME[extname(path)] || 'application/octet-stream' });
    res.end(data);
  } catch {
    if (extname(path) === '' || path === 'index.html') {
      res.writeHead(503, { 'Content-Type': 'text/plain' });
      res.end('Game not built yet. Run: npm run build  (or use: npm start)');
    } else {
      res.writeHead(404);
      res.end();
    }
  }
});

// ---------- Lobby state ----------
const MODES = ['coop', 'dm', 'dmbots'];
const BOT_COUNT = { coop: 8, dm: 0, dmbots: 4 };
const WIN_KILLS = 10;
const MAX_PLAYERS = 8;

let nextId = 1;
const lobbies = new Map(); // code -> lobby

function makeCode() {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ';
  let code;
  do {
    code = Array.from({ length: 4 }, () => chars[Math.floor(Math.random() * chars.length)]).join('');
  } while (lobbies.has(code));
  return code;
}

function lobbySnapshot(l) {
  return {
    t: 'lobby', code: l.code, host: l.host, mode: l.mode, started: l.started,
    players: [...l.players.values()].map(p => ({ id: p.id, name: p.name })),
  };
}

function scores(l) {
  return [...l.players.values()].map(p => ({ id: p.id, name: p.name, k: p.kills, d: p.deaths }));
}

function bcast(l, msg, exceptId = null) {
  const data = JSON.stringify(msg);
  for (const p of l.players.values()) {
    if (p.id !== exceptId && p.ws.readyState === WebSocket.OPEN) p.ws.send(data);
  }
}

function sendTo(l, id, msg) {
  const p = l.players.get(id);
  if (p && p.ws.readyState === WebSocket.OPEN) p.ws.send(JSON.stringify(msg));
}

function leaveLobby(p) {
  const l = p.lobby;
  if (!l) return;
  p.lobby = null;
  l.players.delete(p.id);
  if (l.players.size === 0) {
    lobbies.delete(l.code);
    return;
  }
  const wasHost = l.host === p.id;
  if (wasHost) l.host = l.players.keys().next().value;
  if (l.started && wasHost) {
    // host was simulating the bots — end the round
    l.started = false;
    bcast(l, { t: 'end', reason: 'hostleft', scores: scores(l) });
  }
  bcast(l, lobbySnapshot(l));
}

// ---------- WebSocket handling ----------
const wss = new WebSocketServer({ server: httpServer });

wss.on('connection', (ws) => {
  const p = { id: nextId++, ws, name: 'OPERATOR', lobby: null, kills: 0, deaths: 0 };
  ws.send(JSON.stringify({ t: 'welcome', id: p.id }));

  ws.on('message', (raw) => {
    let msg;
    try { msg = JSON.parse(raw); } catch { return; }
    const l = p.lobby;

    switch (msg.t) {
      case 'create': {
        leaveLobby(p);
        p.name = String(msg.name || 'OPERATOR').slice(0, 14).toUpperCase() || 'OPERATOR';
        const lobby = {
          code: makeCode(), host: p.id, mode: 'coop', started: false,
          players: new Map([[p.id, p]]),
        };
        p.lobby = lobby;
        lobbies.set(lobby.code, lobby);
        bcast(lobby, lobbySnapshot(lobby));
        break;
      }
      case 'join': {
        const lobby = lobbies.get(String(msg.code || '').toUpperCase().trim());
        if (!lobby) return ws.send(JSON.stringify({ t: 'err', m: 'LOBBY NOT FOUND' }));
        if (lobby.started) return ws.send(JSON.stringify({ t: 'err', m: 'MATCH IN PROGRESS' }));
        if (lobby.players.size >= MAX_PLAYERS) return ws.send(JSON.stringify({ t: 'err', m: 'LOBBY FULL' }));
        leaveLobby(p);
        p.name = String(msg.name || 'OPERATOR').slice(0, 14).toUpperCase() || 'OPERATOR';
        p.lobby = lobby;
        lobby.players.set(p.id, p);
        bcast(lobby, lobbySnapshot(lobby));
        break;
      }
      case 'leave':
        leaveLobby(p);
        break;
      case 'mode':
        if (l && l.host === p.id && MODES.includes(msg.mode) && !l.started) {
          l.mode = msg.mode;
          bcast(l, lobbySnapshot(l));
        }
        break;
      case 'start': {
        if (!l || l.host !== p.id || l.started) return;
        l.started = true;
        const spawnOrder = [0, 1, 2, 3, 4, 5, 6, 7].sort(() => Math.random() - 0.5);
        let i = 0;
        const playerList = [...l.players.values()].map(pl => {
          pl.kills = 0; pl.deaths = 0;
          return { id: pl.id, name: pl.name, spawn: spawnOrder[i++ % 8] };
        });
        bcast(l, { t: 'start', mode: l.mode, host: l.host, botCount: BOT_COUNT[l.mode], players: playerList });
        break;
      }
      case 'died': {
        if (!l || !l.started) return;
        p.deaths++;
        const killer = l.players.get(msg.killer);
        if (killer && killer.id !== p.id) killer.kills++;
        bcast(l, { t: 'died', id: p.id, killer: msg.killer, scores: scores(l) });
        if (l.mode !== 'coop' && killer && killer.kills >= WIN_KILLS) {
          l.started = false;
          bcast(l, { t: 'end', reason: 'winner', winner: killer.id, scores: scores(l) });
        }
        break;
      }
      case 'end': // host reports co-op cleared (or failed)
        if (l && l.started && l.host === p.id) {
          l.started = false;
          bcast(l, { t: 'end', reason: msg.reason || 'clear', scores: scores(l) });
        }
        break;
      case 'hit': // route only to the victim
        if (l && l.started) sendTo(l, msg.target, { ...msg, from: p.id });
        break;
      case 'hitBot': // route only to the host (bot authority)
        if (l && l.started) sendTo(l, l.host, { ...msg, from: p.id });
        break;
      case 'state': case 'shoot': case 'bots': case 'botShoot': case 'botDied': case 'respawn':
        if (l && l.started) bcast(l, { ...msg, from: p.id }, p.id);
        break;
    }
  });

  ws.on('close', () => leaveLobby(p));
});

httpServer.listen(PORT, '0.0.0.0', () => {
  console.log(`\nKILLHOUSE server running.`);
  console.log(`  Local:   http://localhost:${PORT}`);
  for (const addrs of Object.values(networkInterfaces())) {
    for (const a of addrs || []) {
      if (a.family === 'IPv4' && !a.internal) {
        console.log(`  Friends: http://${a.address}:${PORT}`);
      }
    }
  }
  console.log('');
});
